// Validar y preparar datos recibidos desde WordPress CRM
// Soporta 3 tipos:
//   type='demo'                  → 1ra reunión con prospecto
//   type='seguimiento_prospecto' → Prospecto que ya tuvo demo (sin ficha/MAXTECH)
//   type='seguimiento'           → Cliente convertido (con ficha/portal/MAXTECH)
try {
  const data = $input.first().json.body || $input.first().json;

  const phone = (data.phone || '').toString().replace(/^\+/, '').replace(/\s/g, '');
  const meetingId = data.meeting_id;
  const clientName = data.client_name || 'Cliente';
  const companyName = data.company_name || '';
  const formattedDate = data.formatted_date || data.meeting_date || '';
  const formattedTime = data.formatted_time || data.meeting_time || '';
  const meetLink = data.meet_link || 'Te llegará por correo';
  const meetingSubject = data.meeting_subject || 'Reunión de Seguimiento';
  const fichaUrl = data.ficha_url || '';
  const meetingType = data.type || 'seguimiento';
  const context = data.context || 'new';
  const prospectTimelineUrl = data.prospect_timeline_url || '';

  // Validar campos requeridos
  if (!meetingId || !phone || phone.length < 8) {
    return {
      json: {
        error: true,
        errorMessage: `Datos incompletos: meeting_id=${meetingId}, phone=${phone} (len=${phone.length})`,
        meeting_id: meetingId || 0,
        phone: phone || 'N/A'
      }
    };
  }

  // Construir saludo personalizado
  let greeting = `Hola ${clientName}`;
  if (companyName) {
    greeting += ` de *${companyName}*`;
  }

  let messageBody = '';
  let btnPrefix = '';

  if (meetingType === 'demo') {
    // === TIPO 1: DEMO - Primera reunión con prospecto ===
    btnPrefix = 'btn_demo';
    if (context === 'reschedule') {
      messageBody = `*Demo Reprogramada*\n\n${greeting}, tu demo con *AutomatizaTech* ha sido reprogramada.\n\n*Nueva Fecha:* ${formattedDate}\n*Nueva Hora:* ${formattedTime} hrs (Chile)\n*Modalidad:* Videollamada Google Meet\n\n📧 *Revisa tu correo*, ahí encontrarás el enlace actualizado de la reunión.\n\n¿Confirmas tu asistencia a la nueva fecha?`;
    } else {
      messageBody = `*Demo Agendada con AutomatizaTech* 🚀\n\n${greeting}, tu demo ha sido agendada exitosamente.\n\n*Fecha:* ${formattedDate}\n*Hora:* ${formattedTime} hrs (Chile)\n*Modalidad:* Videollamada Google Meet\n*Duración:* Aprox. 30 minutos\n\n📧 *Revisa tu correo*, ahí encontrarás el enlace de la reunión.\n\n💡 En la demo te mostraremos cómo la automatización puede transformar tu negocio.\n\n¿Confirmas tu asistencia?`;
    }

  } else if (meetingType === 'seguimiento_prospecto') {
    // === TIPO 2: SEGUIMIENTO DE PROSPECTO - Ya tuvo demo, aún no es cliente ===
    btnPrefix = 'btn_prospect';
    const prospectLine = prospectTimelineUrl ? `\n\n📋 *Tu Seguimiento:*\n${prospectTimelineUrl}\n\n👆 Desde ahí puedes ver el historial completo de tu proceso, propuesta y reuniones.` : '';
    if (context === 'reschedule') {
      messageBody = `*Reunión Reagendada* 📅\n\n${greeting}, tu reunión con *AutomatizaTech* ha sido reagendada.\n\n*Asunto:* ${meetingSubject}\n*Nueva Fecha:* ${formattedDate}\n*Nueva Hora:* ${formattedTime} hrs (Chile)\n*Modalidad:* Videollamada Google Meet${prospectLine}\n\n📧 *Revisa tu correo*, ahí encontrarás el enlace actualizado de la reunión.\n\n¿Confirmas tu asistencia a la nueva fecha?`;
    } else {
      messageBody = `*Reunión Agendada con AutomatizaTech* 📅\n\n${greeting}, se ha agendado una nueva reunión contigo.\n\n*Asunto:* ${meetingSubject}\n*Fecha:* ${formattedDate}\n*Hora:* ${formattedTime} hrs (Chile)\n*Modalidad:* Videollamada Google Meet${prospectLine}\n\n📧 *Revisa tu correo*, ahí encontrarás el enlace de la reunión.\n\n¿Confirmas tu asistencia?`;
    }

  } else {
    // === TIPO 3: SEGUIMIENTO DE CLIENTE - Convertido, con ficha/portal/MAXTECH ===
    btnPrefix = 'btn_followup';
    const fichaLine = fichaUrl ? `\n\n📂 *Tu Portal de Cliente:*\n${fichaUrl}\n\n👆 Desde tu ficha puedes:\n• Ver todo el historial de tu proyecto\n• Revisar reuniones, pagos y entregables\n• Consultar con *MAXTECH* 🤖, tu agente IA especializado que tiene contexto completo de tu proyecto` : '';

    if (context === 'reschedule') {
      messageBody = `*Reunión de Seguimiento Reagendada*\n\n${greeting}, tu reunión de seguimiento con *AutomatizaTech* ha sido reagendada.\n\n*Proyecto:* ${meetingSubject}\n*Nueva Fecha:* ${formattedDate}\n*Nueva Hora:* ${formattedTime} hrs (Chile)${fichaLine}\n\n📧 *Revisa tu correo*, ahí encontrarás el enlace actualizado de la reunión.\n\n¿Confirmas tu asistencia a la nueva fecha?`;
    } else {
      messageBody = `*Reunión de Seguimiento Agendada*\n\n${greeting}, se ha agendado una reunión de seguimiento con *AutomatizaTech*.\n\n*Proyecto:* ${meetingSubject}\n*Fecha:* ${formattedDate}\n*Hora:* ${formattedTime} hrs (Chile)${fichaLine}\n\n📧 *Revisa tu correo*, ahí encontrarás el enlace de la reunión.\n\n¿Confirmas tu asistencia?`;
    }
  }

  return {
    json: {
      error: false,
      meeting_id: meetingId,
      phone: phone,
      clientName: clientName,
      companyName: companyName,
      meetingType: meetingType,
      messageBody: messageBody,
      btnConfirmId: `${btnPrefix}_confirm_${meetingId}`,
      btnRescheduleId: `${btnPrefix}_reschedule_${meetingId}`,
      btnCancelId: `${btnPrefix}_cancel_${meetingId}`
    }
  };
} catch (err) {
  return {
    json: {
      error: true,
      errorMessage: `Error en Prepare WA Message: ${err.message}`,
      meeting_id: 0,
      phone: 'N/A'
    }
  };
}
